def restore_pre_ai14_ordered_radius(current: bytes) -> bytes:
    for new, old in EDITS:
        new, old = new.encode("utf-8"), old.encode("utf-8")
        assert current.count(new) == 1, ("A2-P1c source drift", new[:80])
        current = current.replace(new, old, 1)
    return current
